        else newSelected.add(p.id);
        setSelectedIds(newSelected);
        if (newSelected.size === 0 && selectedGroupNames.size === 0) setListMode('NONE');
        return;
      }
      if (isDeleteMode) {
        if (!p.isMaster) setProfileToDelete(p);
