<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <title>Planetary K-Index Dashboard</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        body { font-family: 'Segoe UI', Arial, sans-serif; background: #0b0e14; color: #c9d1d9; padding: 20px; }
        .container { max-width: 1000px; margin: 0 auto; background: #161b22; padding: 25px; border-radius: 12px; border: 1px solid #30363d; position: relative; }
        h2 { text-align: center; color: #58a6ff; font-weight: 400; margin-bottom: 40px; }
    </style>
</head>
<body>

<div class="container">
    <h2>Planetary K-Index (7-Day Activity)</h2>
    <canvas id="kIndexChart"></canvas>
</div>

<script>
    async function initKIndexChart() {
        const url = 'https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json';

        try {
            const response = await fetch(url);
            const rawData = await response.json();
            const data = rawData.slice(1).slice(-56);

            const labels = data.map(d => d[0]);
            const values = data.map(d => parseFloat(d[1]));

            const barColors = values.map(v => {
                if (v > 9) return '#000000';      // Выше 9
                if (v >= 7) return '#9c27b0';     // 7-9 (Фиолетовый)
                if (v >= 5) return '#ff1744';     // 5-6 (Красный)
                if (v >= 4) return '#ffea00';     // 4 (Желтый)
                return '#00e676';                 // 0-3 (Зеленый)
            });

            const ctx = document.getElementById('kIndexChart').getContext('2d');

            new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: labels,
                    datasets: [{
                        data: values,
                        backgroundColor: barColors,
                        barPercentage: 0.85,
                        categoryPercentage: 1.0
                    }]
                },
                options: {
                    responsive: true,
                    layout: {
                        padding: { top: 30 } // Место для надписи NOW и стрелки
                    },
                    plugins: {
                        legend: { display: false },
                        tooltip: {
                            callbacks: { title: (items) => `Time (UTC): ${items[0].label}` }
                        }
                    },
                    scales: {
                        y: {
                            min: 0, max: 10,
                            ticks: { stepSize: 1, color: '#8b949e' },
                            grid: { color: 'rgba(255,255,255,0.05)' }
                        },
                        x: {
                            grid: { display: false },
                            ticks: {
                                autoSkip: false,
                                maxRotation: 0,
                                color: '#c9d1d9',
                                callback: function(val, index) {
                                    const dateObj = new Date(labels[index] + ' UTC');
                                    // Теперь выводим только даты, без "NOW" внизу
                                    if (dateObj.getUTCHours() === 0) {
                                        return dateObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                                    }
                                    return '';
                                }
                            }
                        }
                    }
                },
                plugins: [
                    {
                        // ПЛАГИН 1: Разделители дней
                        id: 'daySeparator',
                        beforeDraw: (chart) => {
                            const {ctx, chartArea: {top, bottom}, scales: {x}} = chart;
                            ctx.save();
                            ctx.setLineDash([6, 4]);
                            ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
                            labels.forEach((l, i) => {
                                const date = new Date(l + ' UTC');
                                if (date.getUTCHours() === 0 && i > 0) {
                                    const xPos = x.getPixelForValue(i) - (x.getPixelForValue(1) - x.getPixelForValue(0)) / 2;
                                    ctx.beginPath(); ctx.moveTo(xPos, top); ctx.lineTo(xPos, bottom); ctx.stroke();
                                }
                            });
                            ctx.restore();
                        }
                    },
                    {
                        // ПЛАГИН 2: Метка стрелочка "NOW" сверху
                        id: 'nowMarker',
                        afterDraw: (chart) => {
                            const {ctx, scales: {x, y}} = chart;
                            const lastIndex = values.length - 1;
                            const xPos = x.getPixelForValue(lastIndex);
                            const yPos = y.getPixelForValue(values[lastIndex]) - 5; // Чуть выше столбика

                            ctx.save();

                            // Рисуем текст
                            ctx.fillStyle = '#58a6ff';
                            ctx.font = 'bold 11px Arial';
                            ctx.textAlign = 'center';
                            ctx.fillText('NOW', xPos, yPos - 15);

                            // Рисуем треугольник (стрелочку)
                            ctx.beginPath();
                            ctx.moveTo(xPos, yPos);           // Вершина (указывает вниз)
                            ctx.lineTo(xPos - 5, yPos - 10);  // Левый угол
                            ctx.lineTo(xPos + 5, yPos - 10);  // Правый угол
                            ctx.closePath();
                            ctx.fill();

                            ctx.restore();
                        }
                    }
                ]
            });

        } catch (error) {
            console.error("Fetch error:", error);
        }
    }

    initKIndexChart();
</script>

</body>
</html>

