  };

  const getCompatProgress = (idx: number) => {
    const mapping: Record<number, number> = {
      0: 0, 13: 0,
      1: 15, 12: 15,
      2: 35, 11: 35,
      3: 50, 10: 50,
      4: 65, 9: 65,
      5: 85, 8: 85,
      6: 100, 7: 100
