             <div className={`w-4 h-4 rounded border flex items-center justify-center ${isChecked ? 'bg-[#33b5e5] border-[#33b5e5]' : 'border-white/20'}`}>
                {isChecked && <i className="fa-solid fa-check text-[10px] text-black" />}
             </div>
          </div>
        )}
      </div>
